extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var sm: Object = instantiate_script("res://save_manager.gd")
	if not check("script_exists", sm != null, "Lo script save_manager.gd deve essere valido e istanziabile"):
		return
	if FileAccess.file_exists("user://settings.json"):
		DirAccess.remove_absolute("user://settings.json")
	var res_missing = call_if_exists(sm, "load_settings", [], {})
	check("missing", typeof(res_missing) == TYPE_DICTIONARY and res_missing.get("volume", 0) == 80, "Con file mancante load_settings deve restituire le impostazioni predefinite")
	var f := FileAccess.open("user://settings.json", FileAccess.WRITE)
	if f != null:
		f.store_string("{\"volume\": 99, invalid_json_syntax")
		f.close()
	var res_corrupt = call_if_exists(sm, "load_settings", [], {})
	check("corrupt", typeof(res_corrupt) == TYPE_DICTIONARY and res_corrupt.get("volume", 0) == 80, "Con file rovinato load_settings non deve andare in crash e deve restituire i valori di default")
	var f2 := FileAccess.open("user://settings.json", FileAccess.WRITE)
	if f2 != null:
		f2.store_string("{\"volume\": 50, \"fullscreen\": true}")
		f2.close()
	var res_valid = call_if_exists(sm, "load_settings", [], {})
	check("valid", typeof(res_valid) == TYPE_DICTIONARY and res_valid.get("volume", 0) == 50, "Con file valido load_settings deve restituire il dizionario caricato da file")

